<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {ElButton} from 'element-plus'
const props=defineProps<{items:Array<{conflictId:string;title:string;kind:string;localDeleted:boolean;serverDeleted:boolean}>;busy:boolean;completed:number;total:number;message:string}>()
const emit=defineEmits<{resolve:[ids:string[],strategy:'local'|'server']}>()
const selected=ref<string[]>([]),all=computed(()=>props.items.length>0&&selected.value.length===props.items.length)
watch(()=>props.items,items=>{const ids=new Set(items.map(item=>item.conflictId));selected.value=selected.value.filter(id=>ids.has(id))})
function toggleAll(){selected.value=all.value?[]:props.items.map(item=>item.conflictId)}
</script>
<template><section class="setting-group"><h2>同步冲突（{{items.length}}）</h2><div class="conflict-batch-toolbar"><label><input type="checkbox" :checked="all" :disabled="busy" @change="toggleAll"/> 全选</label><span>已选 {{selected.length}} 项</span><ElButton :disabled="busy||!selected.length" @click="emit('resolve',[...selected],'server')">批量采用服务器版</ElButton><ElButton :disabled="busy||!selected.length" @click="emit('resolve',[...selected],'local')">批量保留本机</ElButton></div><p>保留本机包含本机的删除状态；采用服务器版会替换本机修改。处理前会再次确认。</p><div v-if="busy" role="status"><progress :value="completed" :max="total||1"/> {{completed}} / {{total}} 项</div><p v-if="message" role="status">{{message}}</p><article v-for="item in items" :key="item.conflictId" class="conflict-row"><label><input v-model="selected" type="checkbox" :value="item.conflictId" :disabled="busy" :aria-label="`选择冲突：${item.title}`"/></label><span><strong>{{item.title}}</strong><small>{{item.kind}} · 本机{{item.localDeleted?'已删除':'未删除'}} / 服务器{{item.serverDeleted?'已删除':'未删除'}}</small></span><ElButton :disabled="busy" @click="emit('resolve',[item.conflictId],'server')">服务器版</ElButton><ElButton :disabled="busy" @click="emit('resolve',[item.conflictId],'local')">保留本机</ElButton></article></section></template>
<style scoped>.conflict-batch-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.conflict-row{display:flex;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--pc-border)}.conflict-row>span{flex:1;min-width:0}.conflict-row strong,.conflict-row small{display:block;overflow-wrap:anywhere}.conflict-row small,p{color:var(--pc-muted);font-size:12px}input{accent-color:var(--pc-primary)}progress{accent-color:var(--pc-primary)}</style>
